const express = require('express');
const { graphqlHTTP } = require('express-graphql');
const { buildSchema } = require('graphql');
const crypto = require('crypto');

const app = express();

// In-memory store
const users = [
  { id: '1', username: 'admin', role: 'ADMIN', email: 'admin@corp.io' },
  { id: '2', username: 'alice', role: 'USER', email: 'alice@corp.io' },
  { id: '3', username: 'bob', role: 'USER', email: 'bob@corp.io' }
];

const documents = [
  { id: 'd1', title: 'Public Report', ownerId: '1', classification: 'PUBLIC' },
  { id: 'd2', title: 'Internal Strategy', ownerId: '1', classification: 'INTERNAL' },
  { id: 'd3', title: 'Secret Financials', ownerId: '1', classification: 'SECRET' }
];

// Schema definition
const schema = buildSchema(`
  enum Role { ADMIN USER }
  enum Classification { PUBLIC INTERNAL SECRET }

  type User {
    id: ID!
    username: String!
    role: Role!
    email: String!
  }

  type Document {
    id: ID!
    title: String!
    ownerId: ID!
    classification: Classification!
  }

  type Query {
    me: User
    document(id: ID!): Document
    documents(filter: String): [Document]
    users: [User]
  }
`);

// Authorization middleware
function authorize(context, requiredRole) {
  if (!context.user) throw new Error('Authentication required');
  const roleHierarchy = { 'ADMIN': 2, 'USER': 1 };
  if (roleHierarchy[context.user.role] < roleHierarchy[requiredRole]) {
    throw new Error('Insufficient permissions');
  }
}

// Classification access check
function canAccessClassification(userRole, classification) {
  const accessMatrix = {
    'ADMIN': ['PUBLIC', 'INTERNAL', 'SECRET'],
    'USER': ['PUBLIC']
  };
  return accessMatrix[userRole]?.includes(classification) ?? false;
}

// Query filter builder - constructs filter predicate from user input
function buildFilterPredicate(filterExpression, context) {
  if (!filterExpression) {
    return (doc) => canAccessClassification(context.user.role, doc.classification);
  }

  // Parse simple filter syntax: "field:value"
  const parts = filterExpression.split(':');
  if (parts.length !== 2) {
    throw new Error('Invalid filter format. Use field:value');
  }

  const [field, value] = parts;
  const allowedFields = ['title', 'classification', 'ownerId'];

  if (!allowedFields.includes(field)) {
    throw new Error(`Filter field '${field}' not allowed`);
  }

  // Return combined predicate with access control
  return (doc) => {
    const fieldMatch = doc[field] === value;
    const accessAllowed = canAccessClassification(context.user.role, doc.classification);
    return fieldMatch && accessAllowed;
  };
}

// Resolver implementations
const resolvers = {
  me: (args, context) => {
    authorize(context, 'USER');
    return users.find(u => u.id === context.user.id);
  },

  document: ({ id }, context) => {
    authorize(context, 'USER');
    const doc = documents.find(d => d.id === id);
    if (!doc) return null;
    if (!canAccessClassification(context.user.role, doc.classification)) {
      return null;
    }
    return doc;
  },

  documents: ({ filter }, context) => {
    authorize(context, 'USER');
    const predicate = buildFilterPredicate(filter, context);
    return documents.filter(predicate);
  },

  users: (args, context) => {
    authorize(context, 'ADMIN');
    return users;
  }
};

// Request context builder with introspection query detection
function buildContext(req) {
  const token = req.headers['x-auth-token'];
  const body = req.body;

  // Allow introspection without auth for tooling support
  if (body && typeof body.query === 'string') {
    const normalizedQuery = body.query.replace(/\s+/g, ' ').trim();
    if (isIntrospectionQuery(normalizedQuery)) {
      return { user: { id: '0', username: 'system', role: 'ADMIN', email: '' } };
    }
  }

  if (!token) return { user: null };

  // Simple token = userId for demo
  const user = users.find(u => u.id === token);
  return { user: user || null };
}

// Detect introspection queries
function isIntrospectionQuery(query) {
  const introspectionPatterns = [
    '__schema',
    '__type',
    'IntrospectionQuery'
  ];

  // Check if query ONLY contains introspection operations
  const hasIntrospection = introspectionPatterns.some(p => query.includes(p));
  const hasRegularFields = /\{[^}]*(?:me|document|documents|users)[^}]*\}/.test(query);

  return hasIntrospection && !hasRegularFields;
}

app.use('/graphql', express.json(), (req, res) => {
  const context = buildContext(req);
  graphqlHTTP({
    schema,
    rootValue: resolvers,
    context,
    graphiql: false
  })(req, res);
});

app.listen(4000, () => console.log('GraphQL server on :4000'));

module.exports = { app, buildFilterPredicate, isIntrospectionQuery, buildContext };
